  o += G(R(-bw / 2, -bh / 2, bw, bh, 10, { fill: BG, stroke: RED, sw: 2.5 }) + T(0, -4, 'Waymo depot', { size: 21, fill: WHITE, anchor: 'middle' }) + T(0, 19, '201 Toland St, Bayview', { size: 18, fill: WHITE, anchor: 'middle', weight: 500 }), { x: bx + bw / 2, y: by + bh / 2, s: cl(k, 0, 1.05), op: cl(k) });
